mapper.update:
update b_xiecheng_colliding_data_loop_cycle set is_delete = 1,update_time = now() ,
                                                extend = #{rollbackFlag} where id in

    #{id}

mapper.select:
select bmc.cid as cid, bmc.api_code as apiCode, bmc.short_name as shortName, count(dlc.id) AS remainingNumber, '0' as collidingSwitch, '0' as priority, count(dlc.id) as collidingBackNumber, min(dlc.release_time) as collidingStartTime, max(dlc.release_time) as collidingEndTime from b_xiecheng_colliding_data_loop_cycle dlc left join b_marketing_customer bmc on bmc.status = 1 where dlc.is_delete = 0
and bmc.api_code = #{listParam.apiCode}
AND dlc.release_time BETWEEN #{listParam.collidingStartTime} AND #{listParam.collidingEndTime}
GROUP BY DATE_FORMAT(dlc.release_time, '%Y-%m-%d')
ORDER BY ${orderByClause}

select a.id from b_xiecheng_colliding_data_loop_cycle a join ${tableName} c on a.cell_sha256_code_list = c.cell and c.is_delete = 0 left join ( ${queryRuleScoreDataSql} ) b on c.cell = b.cell and b.is_delete = 0 where a.is_delete = 0 and b.id is null and a.release_time >= DATE_ADD(CURDATE(), INTERVAL 1 DAY) and a.release_time < DATE_ADD(CURDATE(), INTERVAL 7 DAY)
and a.id > #{minId}
order by a.id limit #{pageSize};

select a.id
from b_xiecheng_colliding_data_loop_cycle a
join ${tableName} c on a.cell_sha256_code_list = c.cell and c.is_delete = 0
left join ( ${queryRuleScoreDataSql} ) b on c.cell = b.cell and b.is_delete = 0
where a.is_delete = 0 and b.id is null
 and a.release_time >= #{releaseTimeBegin,jdbcType=TIMESTAMP}
and a.release_time <= #{releaseTimeEnd,jdbcType=TIMESTAMP} 

    and a.id > #{minId}

order by a.id limit #{pageSize};

select a.id from b_xiecheng_colliding_data_black_list b
join b_xiecheng_colliding_data_loop_cycle a on a.cell_sha256_code_list = b.cell_sha256 and b.label_type = #{type}
and b.status = 1
where a.is_delete = 0

    and a.id > #{minId}

order by a.id limit #{pageSize};

mapper.update:
update b_xiecheng_colliding_data_loop_cycle
set is_delete = 1, update_time = now(), extend = #{extend}
where is_delete = 0
and id in

    #{id}

